def can_cancel(now: str, booked_at: str, starts_at: str) -> bool:
    now_dt = datetime.fromisoformat(now)
    booked_at_dt = datetime.fromisoformat(booked_at)
    starts_at_dt = datetime.fromisoformat(starts_at)

    # 정정 기간 (10 분): 예약 생성 시간부터
    if now_dt >= booked_at_dt + timedelta(minutes=10):
        return False

    # 일반 취소: 예약 시작 24 시간 전까지
    if now_dt >= starts_at_dt - timedelta(hours=24):
        return False

    # 정정 기간 안이면 일반 마감이 지났어도 시작 전에는 취소 가능
    if now_dt < starts_at_dt:
        return True

